-- oxy:deploy-phase=post
-- Retiring the Stripe-Billing proxy (ADR 0018 "as built"), part 1 of 3
-- (generated, then edited by hand). Post-deploy: the previous image still
-- reads these tables and columns until the rollout finishes.
-- - Drops the proxy's tables: bindings, operations, renewal taxes (ADR 0013's
--   hold), the migration record (#223), the recurring mirrors and their
--   outbox, and the FX-quoted FairCoin rail's subscriptions, invoices and
--   renewal authorizations. Production holds none of their rows' subjects: no
--   cohort was ever configured (read-only probe, 2026-11-04).
-- - Drops #222's held/adopted mode from `subscriptions` (two columns and the
--   CHECK tying them); nothing but the proxy migration ever set them.
-- - Re-adds `events_type_check` and `webhook_endpoints_enabled_events_check`
--   without `billing.observation.updated`, NOT VALID so neither scans under
--   ACCESS EXCLUSIVE; 0081 validates them.
-- `provider_events.retry_after` (a hot table) is dropped alone in 0082.
DROP TABLE "billing_object_bindings" CASCADE;--> statement-breakpoint
DROP TABLE "billing_operations" CASCADE;--> statement-breakpoint
DROP TABLE "billing_proxy_migrations" CASCADE;--> statement-breakpoint
DROP TABLE "billing_renewal_taxes" CASCADE;--> statement-breakpoint
DROP TABLE "faircoin_billing_invoices" CASCADE;--> statement-breakpoint
DROP TABLE "faircoin_billing_subscriptions" CASCADE;--> statement-breakpoint
DROP TABLE "faircoin_renewal_authorizations" CASCADE;--> statement-breakpoint
DROP TABLE "recurring_mirrors" CASCADE;--> statement-breakpoint
DROP TABLE "recurring_observation_outbox" CASCADE;--> statement-breakpoint
ALTER TABLE "events" DROP CONSTRAINT "events_type_check";--> statement-breakpoint
ALTER TABLE "subscriptions" DROP CONSTRAINT "subscriptions_provider_handoff_check";--> statement-breakpoint
ALTER TABLE "webhook_endpoints" DROP CONSTRAINT "webhook_endpoints_enabled_events_check";--> statement-breakpoint
ALTER TABLE "subscriptions" DROP COLUMN "provider_billed_until";--> statement-breakpoint
ALTER TABLE "subscriptions" DROP COLUMN "provider_handoff_pending";--> statement-breakpoint
